fields.html_body:
{{block:abcona_header_blau}}
{{block:label_bestaetigt}}
<p>Hallo <strong>{name}</strong>,</p>
<p>Ihr Berater-Profil wurde erfolgreich erstellt.</p>
<a href="{cv_link}" style="display:inline-block;background:#163258;color:white;padding:10px 20px;border-radius:5px;text-decoration:none;font-weight:600;">Profil ansehen</a>
<p style="margin:16px 0 0;font-size:12px;color:#6c757d;">Version: {cv_version} &nbsp;·&nbsp; Erstellt am: {created_date}</p>
{{block:signature}}

{{block:abcona_header_blau}}
{{block:label_warnung}}
<p>Hallo {name},</p>
<p>Ihre E-Mail konnte leider nicht automatisch verarbeitet werden.</p>
<div style="background:#eef2f5;border-left:3px solid #ef4444;border-radius:0 4px 4px 0;padding:14px 16px;font-size:12px;line-height:1.8;">
<div><strong>Original Betreff:</strong> {original_subject}</div>
<div><strong>Import Zeit:</strong> {import_time}</div>
<div><strong>E-Mail ID:</strong> {email_id}</div>
<div><strong>Fehlercode:</strong> {error_code}</div>
</div>
<div style="background:#eef2f5;border-left:3px solid #ef4444;border-radius:0 4px 4px 0;padding:14px 16px;font-size:12px;margin-top:12px;">
<strong>Problem:</strong><br>{error_detail}
</div>
<div style="background:#e8f0f8;border-left:3px solid #163258;border-radius:0 4px 4px 0;padding:14px 16px;font-size:12px;margin-top:12px;">
<strong>Lösung:</strong><br>{solution}
</div>
<p style="font-size:12px;">Bitte korrigieren Sie die genannten Punkte und senden Sie Ihre Bewerbung erneut.</p>
{{block:support_kontakt}}
{{block:footer_auto_reply}}

{{block:abcona_header_blau}}
{{block:label_warnung}}
<p>Hallo {name},</p>
<p>Die Verarbeitung Ihres CVs ist leider fehlgeschlagen.</p>
<div style="background:#eef2f5;border-left:3px solid #ef4444;border-radius:0 4px 4px 0;padding:14px 16px;font-size:12px;line-height:1.8;">
<div><strong>Name:</strong> {name}</div>
<div><strong>AID:</strong> {aid}</div>
<div><strong>Fehlercode:</strong> {error_code}</div>
<div><strong>Details:</strong> {error_detail}</div>
<div><strong>E-Mail ID:</strong> {email_id}</div>
</div>
{{block:support_kontakt}}
{{block:footer_auto_reply}}

{{block:abcona_header_blau}}
<p>{body}</p>
{{block:signature}}
